  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C44"],
      "claim": "The fed-state absolute bioavailability of GSK1322322 was 77% in healthy volunteers after a meal, directly supporting F >= 20% under the query's fed condition.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "Prucalopride has absolute oral bioavailability greater than 90% and its absorption is not influenced by food, supporting high oral bioavailability in the fed state.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C19"],
      "claim": "Emtricitabine has a mean absolute oral bioavailability of 93% and is reported to be unaffected by food, providing additional high-transfer support for high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Asciminib is predicted to have an absolute oral bioavailability of approximately 73%, consistent with high oral bioavailability.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "Multiple highly transferable experimental analogues show absolute oral bioavailability values well above 20%, including a direct fed-state measurement of 77% and food-insensitive high-absorption drugs. No evidence supports F < 20%.",
  "evidence_gaps": [
    "No direct experimental bioavailability data exist for the query molecule itself.",
    "Fed-state-specific bioavailability data are available for only one analogue; other high-transfer measurements were made under fasted or unspecified conditions.",
    "Metabolic first-pass extraction and solubility-limited absorption for the query are not experimentally characterized."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

